class Solution {
public:
    int uniquePathsIII(vector<vector<int>>& grid) {
        int rows = grid.size(), cols = grid[0].size();
        int sr = 0, sc = 0, walkable = 0;
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] != -1) walkable++;
                if (grid[r][c] == 1) {
                    sr = r;
                    sc = c;
                }
            }
        }
        auto dfs = [&](auto& self, int r, int c, int remain) -> int {
            if (grid[r][c] == 2) return remain == 1 ? 1 : 0;
            int temp = grid[r][c];
            grid[r][c] = -1;
            int paths = 0;
            int dr[4] = {-1, 1, 0, 0};
            int dc[4] = {0, 0, -1, 1};
            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] != -1) {
                    paths += self(self, nr, nc, remain - 1);
                }
            }
            grid[r][c] = temp;
            return paths;
        };
        return dfs(dfs, sr, sc, walkable);
    }
};

class Solution {
    private int rows, cols;
    private int dfs(int[][] grid, int r, int c, int remain) {
        if (grid[r][c] == 2) return remain == 1 ? 1 : 0;
        int temp = grid[r][c];
        grid[r][c] = -1;
        int paths = 0;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] != -1) {
                paths += dfs(grid, nr, nc, remain - 1);
            }
        }
        grid[r][c] = temp;
        return paths;
    }
    public int uniquePathsIII(int[][] grid) {
        rows = grid.length;
        cols = grid[0].length;
        int sr = 0, sc = 0, walkable = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != -1) walkable++;
                if (grid[r][c] == 1) {
                    sr = r;
                    sc = c;
                }
            }
        }
        return dfs(grid, sr, sc, walkable);
    }
}

var uniquePathsIII = function(grid) {
    const rows = grid.length, cols = grid[0].length;
    let sr = 0, sc = 0, walkable = 0;
    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (grid[r][c] !== -1) walkable++;
            if (grid[r][c] === 1) {
                sr = r;
                sc = c;
            }
        }
    }
    const dfs = (r, c, remain) => {
        if (grid[r][c] === 2) return remain === 1 ? 1 : 0;
        const temp = grid[r][c];
        grid[r][c] = -1;
        let paths = 0;
        const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] !== -1) {
                paths += dfs(nr, nc, remain - 1);
            }
        }
        grid[r][c] = temp;
        return paths;
    };
    return dfs(sr, sc, walkable);
};
